//! Generated complex metadata and checked scalar/output boundary semantics.
use super::{
    finish, BinaryUfunc, MaskedCondition, MaskedError, MaskedValue, Operation, Precision, Unary,
};

/// A complex value generated by an accepted real-input scalar expression.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ComplexValue {
    /// Real component in the enclosing value's selected floating precision.
    pub real: f64,
    /// Imaginary component in the enclosing value's selected floating precision.
    pub imag: f64,
}

impl ComplexValue {
    /// Round both components at a real NumPy complex casting boundary.
    fn rounded(self, p: Precision) -> Self {
        match p {
            Precision::F32 => Self {
                real: (self.real as f32) as f64,
                imag: (self.imag as f32) as f64,
            },
            Precision::F64 => self,
        }
    }
}

/// Infer whether a branch has an unsupported object dtype without converting its data prematurely.
pub(super) fn object_branch(value: MaskedValue) -> bool {
    value.object_result || (value.weak && value.wide_integer.is_some() && value.integer.is_none())
}
/// Select the real precision underlying NumPy complex promotion.
fn precision(a: MaskedValue, b: MaskedValue, strong_constants: bool) -> Precision {
    if !strong_constants && a.weak != b.weak {
        let (weak, strong) = if a.weak { (a, b) } else { (b, a) };
        if strong.complex.is_some() {
            return strong.precision;
        }
        if weak.complex.is_some() {
            return if strong.integer.is_some() || strong.wide_integer.is_some() {
                Precision::F64
            } else {
                strong.precision
            };
        }
    }
    let wide = |x: MaskedValue| {
        x.precision == Precision::F64 && x.integer.is_none()
            || x.integer.is_some_and(|i| i.kind.bits() >= 32)
            || x.wide_integer.is_some()
    };
    if wide(a) || wide(b) {
        Precision::F64
    } else {
        Precision::F32
    }
}
/// Cast real or generated-complex data directly at its operation's chosen precision.
fn components(value: MaskedValue, p: Precision) -> Result<ComplexValue, MaskedError> {
    if let Some(complex) = value.complex {
        return Ok(complex.rounded(p));
    }
    let value = super::integers::to_float(value, p);
    if let Some(error) = value.error {
        return Err(error);
    }
    Ok(ComplexValue {
        real: value.value,
        imag: 0.0,
    })
}
/// Form a complex result while preserving source mask, rank, scalar dispatch, and profile.
fn result(
    operands: (MaskedValue, MaskedValue),
    value: ComplexValue,
    p: Precision,
    mask: bool,
    ma: bool,
    weak: bool,
    arithmetic: bool,
) -> MaskedValue {
    let (a, b) = operands;
    let value = value.rounded(p);
    let mut result = MaskedValue::new(value.real, mask, ma, p)
        .with_scalar_array(a.is_scalar_array && b.is_scalar_array)
        .with_fill_value(if a.is_masked_array {
            a.fill_value
        } else {
            b.fill_value
        })
        .with_math_profile(super::profile(a, b));
    result.complex = Some(value);
    result.weak = weak;
    result.is_numpy_scalar = result.is_scalar_array && !ma && !weak;
    finish(result, arithmetic)
}
/// Evaluate a Python real-negative fractional power that generates a Python complex scalar.
pub(super) fn real_power(a: MaskedValue, b: MaskedValue) -> Option<MaskedValue> {
    if !(a.weak
        && b.weak
        && a.value.is_finite()
        && b.value.is_finite()
        && a.value < 0.0
        && b.value.fract() != 0.0)
    {
        return None;
    }
    let magnitude = (-a.value).powf(b.value);
    if magnitude.is_infinite() {
        return Some(super::integers::failure(
            a,
            MaskedError::PythonFloatOverflow,
        ));
    }
    let angle = std::f64::consts::PI * b.value;
    Some(result(
        (a, b),
        ComplexValue {
            real: magnitude * angle.cos(),
            imag: magnitude * angle.sin(),
        },
        Precision::F64,
        false,
        false,
        true,
        true,
    ))
}
/// Complex division uses a scaled ratio to avoid avoidable intermediate overflow.
fn divide(a: ComplexValue, b: ComplexValue) -> ComplexValue {
    if b.real.abs() >= b.imag.abs() {
        let r = b.imag / b.real;
        let d = b.real + b.imag * r;
        ComplexValue {
            real: (a.real + a.imag * r) / d,
            imag: (a.imag - a.real * r) / d,
        }
    } else {
        let r = b.real / b.imag;
        let d = b.imag + b.real * r;
        ComplexValue {
            real: (a.real * r + a.imag) / d,
            imag: (a.imag * r - a.real) / d,
        }
    }
}
/// Compute the arithmetic required by generated complex prefixes without accepting Python complex inputs.
pub(super) fn arithmetic(a: MaskedValue, b: MaskedValue, operation: Operation) -> MaskedValue {
    let ma = a.is_masked_array || b.is_masked_array;
    let ufunc = a.is_numpy_scalar && b.is_masked_array;
    let p = precision(a, b, ma);
    let x = match components(a, p) {
        Ok(v) => v,
        Err(e) => return super::integers::failure(a, e),
    };
    let y = match components(b, p) {
        Ok(v) => v,
        Err(e) => return super::integers::failure(b, e),
    };
    let python = a.weak && b.weak
        || a.weak
            && a.complex.is_some()
            && b.is_numpy_scalar
            && !b.is_masked_array
            && b.complex.is_none()
            && b.integer.is_none()
            && b.precision == Precision::F64;
    if python && matches!(operation, Operation::Div) && y.real == 0.0 && y.imag == 0.0 {
        return super::integers::failure(a, MaskedError::PythonZeroDivision);
    }
    let compute = |x: ComplexValue, y: ComplexValue| match operation {
        Operation::Add => ComplexValue {
            real: x.real + y.real,
            imag: x.imag + y.imag,
        },
        Operation::Sub => ComplexValue {
            real: x.real - y.real,
            imag: x.imag - y.imag,
        },
        Operation::Mul => {
            if p == Precision::F32 {
                let (ar, ai, br, bi) = (x.real as f32, x.imag as f32, y.real as f32, y.imag as f32);
                ComplexValue {
                    real: (ar * br - ai * bi) as f64,
                    imag: (ar * bi + ai * br) as f64,
                }
            } else {
                ComplexValue {
                    real: x.real * y.real - x.imag * y.imag,
                    imag: x.real * y.imag + x.imag * y.real,
                }
            }
        }
        Operation::Div => divide(x, y),
        Operation::Pow => {
            if y.real == 0.0 && y.imag == 0.0 {
                return ComplexValue {
                    real: 1.0,
                    imag: 0.0,
                };
            }
            let length = x.real.hypot(x.imag);
            let argument = x.imag.atan2(x.real);
            let magnitude = length.powf(y.real) * (-y.imag * argument).exp();
            let phase = argument * y.real + y.imag * length.ln();
            ComplexValue {
                real: magnitude * phase.cos(),
                imag: magnitude * phase.sin(),
            }
        }
    };
    let mask = a.mask || b.mask;
    let value = if ma && mask && !ufunc {
        x
    } else {
        compute(x, y)
    };
    if python
        && matches!(operation, Operation::Pow)
        && x.real.is_finite()
        && x.imag.is_finite()
        && y.real.is_finite()
        && y.imag.is_finite()
        && (!value.real.is_finite() || !value.imag.is_finite())
    {
        return super::integers::failure(a, MaskedError::PythonFloatOverflow);
    }
    result((a, b), value, p, mask, ma, python && !ma, !ufunc)
}
/// Preserve complex dtype from either branch, including an unselected generated imaginary value.
pub(super) fn select(condition: MaskedCondition, yes: MaskedValue, no: MaskedValue) -> MaskedValue {
    let p = precision(yes, no, false);
    let chosen = if condition.value { yes } else { no };
    let value = match components(chosen, p) {
        Ok(v) => v,
        Err(e) => return super::integers::failure(chosen, e),
    };
    let mut result = MaskedValue::new(value.real, false, false, p)
        .with_scalar_array(condition.is_scalar_array && yes.is_scalar_array && no.is_scalar_array)
        .with_math_profile(super::profile(yes, no));
    result.complex = Some(value);
    result.error = condition.error.or(yes.error).or(no.error);
    result
}
/// Compare generated NumPy complex values lexicographically; Python complex ordering is rejected.
pub(super) fn compare(a: MaskedValue, b: MaskedValue, operation: u8) -> Result<bool, MaskedError> {
    if a.weak && b.weak {
        return Err(MaskedError::UnsupportedComplexOperation);
    }
    let p = precision(a, b, false);
    let x = components(a, p)?;
    let y = components(b, p)?;
    Ok(match operation {
        0 => x.real > y.real || x.real == y.real && x.imag > y.imag,
        1 => x.real < y.real || x.real == y.real && x.imag < y.imag,
        _ => x.real > y.real || x.real == y.real && x.imag >= y.imag,
    })
}
/// Apply supported complex ufunc selection; atan2 has no complex loop.
pub(super) fn ufunc(a: MaskedValue, b: MaskedValue, operation: BinaryUfunc) -> MaskedValue {
    if matches!(operation, BinaryUfunc::Atan2) {
        return super::integers::failure(a, MaskedError::UnsupportedComplexOperation);
    }
    let p = precision(a, b, false);
    let x = match components(a, p) {
        Ok(v) => v,
        Err(e) => return super::integers::failure(a, e),
    };
    let y = match components(b, p) {
        Ok(v) => v,
        Err(e) => return super::integers::failure(b, e),
    };
    let nan = |v: ComplexValue| v.real.is_nan() || v.imag.is_nan();
    let choose_x = if nan(x) {
        true
    } else if nan(y) {
        false
    } else if matches!(operation, BinaryUfunc::Minimum) {
        x.real < y.real || x.real == y.real && x.imag < y.imag
    } else {
        x.real > y.real || x.real == y.real && x.imag > y.imag
    };
    result(
        (a, b),
        if choose_x { x } else { y },
        p,
        a.mask || b.mask,
        a.is_masked_array || b.is_masked_array,
        false,
        false,
    )
}
/// Negate generated complex components; real-only ufunc loops reject a complex intermediate explicitly.
pub(super) fn unary(value: MaskedValue, operation: Unary) -> MaskedValue {
    if !matches!(operation, Unary::Negative) {
        return super::integers::failure(value, MaskedError::UnsupportedComplexOperation);
    }
    let mut result = value;
    let x = value.complex.unwrap();
    result.value = -x.real;
    result.complex = Some(ComplexValue {
        real: -x.real,
        imag: -x.imag,
    });
    finish(result, false)
}

impl MaskedValue {
    /// Reject eager source failures or an unsupported arbitrary-precision/object result before encoding.
    pub fn validate_output(self) -> Result<Self, MaskedError> {
        if let Some(error) = self.error {
            return Err(error);
        }
        if !self.empty_array
            && self.wide_integer.is_some()
            && self.integer.is_none()
            && self.complex.is_none()
        {
            return Err(MaskedError::UnsupportedIntegerObject);
        }
        Ok(self)
    }
    /// Check every eagerly evaluated field error before applying output-only object restrictions.
    pub fn validate_outputs(values: &[Self]) -> Result<(), MaskedError> {
        if let Some(error) = values.iter().find_map(|x| x.error) {
            return Err(error);
        }
        for value in values {
            value.validate_output()?;
        }
        Ok(())
    }
}
